20	
21	Keep this as one compact dependency-free Node.js packet using the existing function/configuration boundary. Preserve unrelated fixture content. No commit, installation or external action is authorized.
22	export function parseTimeout(raw) {
23	  if (raw === undefined) return 5000;
24	  if (!/^[0-9]+$/.test(raw) || Number(raw) < 1 || Number(raw) > 10) throw new Error('INVALID_TIMEOUT');
25	  return Number(raw) * 1000;
26	}
27	#!/usr/bin/env node
28	import { parseTimeout } from './configuration.mjs';
29	try { process.stdout.write(JSON.stringify({timeoutMs:parseTimeout(process.env.TIMEOUT_SECONDS),format:'json'})+'\n'); }
30	catch { process.stderr.write('INVALID_TIMEOUT\n'); process.exitCode=2; }
31	import test from 'node:test';
32	import assert from 'node:assert/strict';
33	import { parseTimeout } from './configuration.mjs';
34	test('existing default and accepted value remain stable',()=>{assert.equal(parseTimeout(undefined),5000);assert.equal(parseTimeout('5'),5000);assert.throws(()=>parseTimeout('0'),/INVALID_TIMEOUT/);});
35	import { mkdirSync, mkdtempSync, openSync, closeSync, readFileSync, rmSync } from 'node:fs';
36	import { dirname, join } from 'node:path';
37	import { fileURLToPath } from 'node:url';
38	import { spawnSync } from 'node:child_process';
39	const appRoot = dirname(fileURLToPath(import.meta.url));
40	export function runCli(args, options = {}) {
41	  const tempRoot = join(appRoot, '.tmp');
42	  mkdirSync(tempRoot, { recursive: true });
43	  const folder = mkdtempSync(join(tempRoot, 'child-'));
44	  const stdoutPath = join(folder, 'stdout'), stderrPath = join(folder, 'stderr');
45	  let stdoutFd, stderrFd;
46	  try {
47	    stdoutFd = openSync(stdoutPath, 'w');
48	    stderrFd = openSync(stderrPath, 'w');
49	    const result = spawnSync(process.execPath, ['cli.mjs', ...args], {
50	      cwd: appRoot, env: { ...process.env, ...options.env },
51	      stdio: ['ignore', stdoutFd, stderrFd], timeout: 5000,
52	    });
53	    if (result.error) throw result.error;
54	    return { status: result.status, signal: result.signal,
55	      stdout: readFileSync(stdoutPath, 'utf8'), stderr: readFileSync(stderrPath, 'utf8') };
56	  } finally {
57	    if (stdoutFd !== undefined) closeSync(stdoutFd);
58	    if (stderrFd !== undefined) closeSync(stderrFd);
59	    rmSync(folder, { recursive: true, force: true });
60	  }
61	}
